DO $$DECLARE def text; BEGIN
 def:=pg_get_functiondef('private.k3_write_guard(date)'::regprocedure);
 def:=replace(def,'SELECT * INTO s FROM public.k3_settings WHERE id FOR SHARE;','PERFORM pg_advisory_xact_lock(hashtext(''k3owner''),hashtext(auth.uid()::text)); SELECT * INTO s FROM public.k3_settings WHERE id FOR SHARE;'); EXECUTE def;
 def:=pg_get_functiondef('public.k3_task_save(jsonb)'::regprocedure);
 def:=replace(def,'VALUES(auth.uid(),_date,now())','VALUES(auth.uid(),_date,CASE WHEN coalesce(current_setting(''k3.creating_unscheduled'',true),'''')=''yes'' THEN NULL ELSE now() END)');
 def:=replace(def,'AND is_focus AND deleted_at IS NULL AND id IS DISTINCT FROM _id','AND is_focus AND deleted_at IS NULL AND NOT is_unscheduled AND id IS DISTINCT FROM _id');
 def:=replace(def,'IF coalesce((p->>''is_focus'')::boolean,false) AND','IF coalesce(current_setting(''k3.creating_unscheduled'',true),'''')<>''yes'' AND coalesce((p->>''is_focus'')::boolean,false) AND');
 def:=replace(def,'created_by,updated_by,request_key)','created_by,updated_by,request_key,is_unscheduled)');
 def:=replace(def,'auth.uid(),auth.uid(),_key) RETURNING','auth.uid(),auth.uid(),_key,coalesce(current_setting(''k3.creating_unscheduled'',true),'''')=''yes'') RETURNING');
 EXECUTE def;
 def:=pg_get_functiondef('public.k3_plan_task_save(jsonb)'::regprocedure);
 def:=replace(def,'result:=public.k3_task_save(p);','IF t.id IS NULL AND nullif(_payload->>''work_date'','''') IS NULL THEN PERFORM set_config(''k3.creating_unscheduled'',''yes'',true); END IF; result:=public.k3_task_save(p); PERFORM set_config(''k3.creating_unscheduled'','''',true);');
 EXECUTE def;
 def:=pg_get_functiondef('public.k3_task_schedule(uuid,date,bigint)'::regprocedure);
 def:=replace(def,'original_work_date=coalesce(original_work_date,work_date,_date)','original_work_date=coalesce(original_work_date,CASE WHEN is_unscheduled THEN _date ELSE work_date END)');
 EXECUTE def;
END$$;
CREATE FUNCTION private.k3_period_comment_scope(_actor uuid,_comment uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM public.k3_period_comments c WHERE c.id=_comment AND ((c.user_id=_actor AND public.k3_can(_actor,'k3.use')) OR (public.k3_can(_actor,'k3.view_scope') AND public.biz_scope_ok(_actor,c.user_id,public.biz_department_at(c.user_id,c.period_start),(c.period_start::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh')))))$$;
REVOKE ALL ON FUNCTION private.k3_period_comment_scope(uuid,uuid) FROM PUBLIC,anon,authenticated;
DROP POLICY k3_period_comment_own ON public.k3_period_comments;
CREATE POLICY k3_period_comment_own ON public.k3_period_comments FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.k3_can(auth.uid(),'k3.use'));
DROP POLICY k3_comments_select ON public.k3_comments;
CREATE POLICY k3_comments_select ON public.k3_comments FOR SELECT TO authenticated USING(public.k3_day_scope_ok(auth.uid(),day_id));
DROP POLICY k3_days_select ON public.k3_days;
CREATE POLICY k3_days_select ON public.k3_days FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.k3_can(auth.uid(),'k3.use'));
DROP POLICY k3_tasks_select ON public.k3_tasks;
CREATE POLICY k3_tasks_select ON public.k3_tasks FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.k3_can(auth.uid(),'k3.use'));
CREATE FUNCTION private.k3_goal_consistency() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$BEGIN IF NEW.period_start<>public.k3_period_start(NEW.period_type,NEW.period_start) OR NEW.period_end<>public.k3_period_end(NEW.period_type,NEW.period_start) THEN RAISE EXCEPTION 'Khoảng kỳ mục tiêu không hợp lệ.'; END IF; RETURN NEW; END$$;
CREATE TRIGGER k3_goal_consistency BEFORE INSERT OR UPDATE ON public.k3_goals FOR EACH ROW EXECUTE FUNCTION private.k3_goal_consistency();
CREATE FUNCTION private.k3_action_consistency() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$BEGIN IF NOT EXISTS(SELECT 1 FROM public.k3_goals WHERE id=NEW.goal_id AND user_id=NEW.user_id) THEN RAISE EXCEPTION 'Hành động không khớp chủ mục tiêu.'; END IF; RETURN NEW; END$$;
CREATE TRIGGER k3_action_consistency BEFORE INSERT OR UPDATE ON public.k3_actions FOR EACH ROW EXECUTE FUNCTION private.k3_action_consistency();